(()=>{
'use strict';
const V='1.0.0-level25-receipt-bundle';
const K20='pmp_level20_certification_chain_summary_lock_v1',K21='pmp_level21_one_tap_full_chain_retest_lock_v1',K22='pmp_level22_exportable_certification_receipt_v1',K23='pmp_level23_export_receipt_integrity_check_v1',K24='pmp_level24_tampered_receipt_rejection_test_v1',K25='pmp_level25_portable_verification_packet_v1';
function W(){try{return window.top||window}catch(e){return window}}
function get(k,d){try{return JSON.parse(W().localStorage.getItem(k)||'')||d}catch(e){return d}}
function put(k,v){try{W().localStorage.setItem(k,JSON.stringify(v,null,2))}catch(e){}return v}
function h(s){let x=2166136261;s=String(s||'');for(let i=0;i<s.length;i++){x^=s.charCodeAt(i);x=Math.imul(x,16777619)}return(x>>>0).toString(16).padStart(8,'0')}
function docs(r,a,n){a=a||[];n=n||0;if(!r||n>8)return a;try{a.push(r);r.querySelectorAll('iframe').forEach(f=>{try{let d=f.contentDocument||(f.contentWindow&&f.contentWindow.document);if(d)docs(d,a,n+1)}catch(e){}})}catch(e){}return a}
function good(v,s){return !!(v&&v.status===s&&v.passed!==false)}
function build(){let l20=get(K20,null),l21=get(K21,null),l22=get(K22,null),l23=get(K23,null),l24=get(K24,null);let checks={level20:good(l20,'CERTIFICATION_CHAIN_SUMMARY_LOCK_PASSED')?'PASS':'FAIL',level21:good(l21,'ONE_TAP_FULL_CHAIN_RETEST_LOCK_PASSED')?'PASS':'FAIL',level22:good(l22,'EXPORTABLE_CERTIFICATION_RECEIPT_READY')?'PASS':'FAIL',level23:good(l23,'EXPORT_RECEIPT_INTEGRITY_CHECK_PASSED')?'PASS':'FAIL',level24:good(l24,'TAMPERED_RECEIPT_REJECTION_TEST_PASSED')?'PASS':'FAIL'};let pass=Object.values(checks).every(x=>x==='PASS');let body={type:'PMP_LEVEL_25_RECEIPT_BUNDLE',version:V,created_at:new Date().toISOString(),status:pass?'PORTABLE_VERIFICATION_PACKET_READY':'PORTABLE_VERIFICATION_PACKET_FAILED',source_hash:(l21&&l21.source_hash)||(l20&&l20.source_hash)||null,level10_hash:l21&&l21.level10_hash||null,level20_summary_hash:l21&&l21.level20_summary_hash||l20&&l20.summary_hash||null,level21_retest_hash:l21&&l21.retest_hash||null,level22_export_hash:l22&&l22.export_hash||null,level23_integrity_hash:l23&&l23.integrity_hash||null,level24_rejection_hash:l24&&l24.rejection_test_hash||null,original_receipt_hash:l24&&l24.original_receipt_hash||l23&&l23.receipt_hash||null,tampered_receipt_hash:l24&&l24.tampered_receipt_hash||null,checks,receipt_text:l22&&l22.receipt_text||''};let first=JSON.stringify(body,null,2);body.packet_hash=h(first);let json=JSON.stringify(body,null,2);let text='PMP LEVEL 25 RECEIPT BUNDLE\nStatus: '+body.status+'\nBundle hash: '+body.packet_hash+'\nSource hash: '+(body.source_hash||'none')+'\nLevel 10 hash: '+(body.level10_hash||'none')+'\nLevel 21 re-test hash: '+(body.level21_retest_hash||'none')+'\nLevel 22 export hash: '+(body.level22_export_hash||'none')+'\nLevel 23 integrity hash: '+(body.level23_integrity_hash||'none')+'\nLevel 24 rejection hash: '+(body.level24_rejection_hash||'none')+'\n\nJSON\n'+json;return put(K25,{level:25,type:'PORTABLE_VERIFICATION_PACKET',version:V,at:new Date().toISOString(),status:body.status,passed:pass,packet_hash:body.packet_hash,packet_char_count:text.length,source_hash:body.source_hash,level10_hash:body.level10_hash,level21_retest_hash:body.level21_retest_hash,checks,packet_text:text})}
function show(x){if(!x)return'Level 25 ready.';let c=x.checks||{};return'Level 25\nStatus: '+(x.status||'NONE')+'\nPacket ready: '+(x.passed?'YES':'NO')+'\nLevel 20 summary: '+(c.level20||'none')+'\nLevel 21 re-test: '+(c.level21||'none')+'\nLevel 22 export: '+(c.level22||'none')+'\nLevel 23 integrity: '+(c.level23||'none')+'\nLevel 24 rejection: '+(c.level24||'none')+'\nSource hash: '+(x.source_hash||'none')+'\nLevel 10 hash: '+(x.level10_hash||'none')+'\nBundle hash: '+(x.packet_hash||'none')+'\nBundle characters: '+(x.packet_char_count||0)+'\n\nBundle text:\n'+(x.packet_text||'')}
function sec(){return'<div data-level25-bundle style="margin-top:8px;padding:8px;border-radius:10px;border:1px solid rgba(0,0,0,.08)"><h4 style="margin:0 0 4px">Level 25 — Portable Verification Packet</h4><p class="sub">Packages the receipt, hashes, integrity proof, and rejection proof into one portable packet.</p><div class="grid"><button class="mini" data-l25-run>Generate Packet</button><button class="mini" data-l25-view>View Packet Lock</button></div><pre class="note" data-l25-out style="max-height:500px;overflow:auto;white-space:pre-wrap">Level 25 ready.</pre></div>'}
function patch(d){let root=d.querySelector('[data-source-reference-gate-level4]');if(!root)return;let head=root.querySelector('h4');if(head&&!root.querySelector('[data-l25-badge]'))head.insertAdjacentHTML('afterend','<div data-l25-badge style="margin:4px 0 8px;padding:8px;border-radius:10px;border:2px solid rgba(0,0,0,.18);font-weight:950">Level 25: Portable Verification Packet — READY</div>');if(!root.querySelector('[data-level25-bundle]'))root.insertAdjacentHTML('beforeend',sec());let out=root.querySelector('[data-l25-out]'),run=root.querySelector('[data-l25-run]'),vw=root.querySelector('[data-l25-view]');if(run)run.onclick=()=>{out.textContent=show(build())};if(vw)vw.onclick=()=>{out.textContent=show(get(K25,null))}}
function scan(){docs(W().document).forEach(d=>{try{patch(d)}catch(e){}})}
W().PMPPortableVerificationPacketLevel25V1={version:V,run:build,view:()=>get(K25,null),render:show};
window.addEventListener('load',()=>[300,1000,2500,5000].forEach(t=>setTimeout(scan,t)));
setInterval(scan,1000);scan();
})();